'use strict';

const fs=require('fs');
const assert=require('assert');

const file=process.argv[2];
assert(file,'usage: node tests/browser/assert-rendered-dom.js <dumped-dom.html>');
const dom=fs.readFileSync(file,'utf8');

assert(/<title>TrainLog Pro v[^<]+<\/title>/.test(dom),'browser did not load TrainLog Pro');
const today=dom.match(/id="todayText"[^>]*>([^<]+)<\/div>/)?.[1]?.trim();
assert(today,'startup JavaScript did not render #todayText');

// These strings are generated by js/app.js at runtime and are not static index.html content.
[
  '本週訓練',
  '有氧分鐘',
  '近 30 天訓練量',
  '全部肌群',
  '資料不足'
].forEach(text=>assert(dom.includes(text),'runtime DOM is missing expected rendered text: '+text));

// Fresh storage should still render the records empty-state instead of failing during startup.
assert(dom.includes('這個月份沒有符合條件的紀錄。'),'records renderer did not complete');

console.log('browser smoke: startup JavaScript rendered home, records and analysis DOM successfully');
